import { Meta, StoryObj } from "@storybook/react";
import { ListBlock, ListTransformerProps } from "../list-block";
import { ProductCardProps } from "@/core/components/modules/product-card/product-card";
import { ProductGroup } from "../product-list-renderer/product-list-renderer";
import { NestedTagFilterer } from "../nested-tag-filterer/nested-tag-filterer";
import { StickyFilter } from "./sticky-filter";
import styles from "./sticky-filter.stories.module.less";
import { Sorter } from "../sorter/sorter";
import { action } from "storybook/actions";
import { ComponentProps } from "react";

const exampleProduct = (pr: Partial<ProductCardProps>): ProductCardProps => ({
  heading: "Ticket to ride",
  imageUrl:
    "https://images.ctfassets.net/ds6dz7ilx8up/1OyurI2ZkeLiVyg5HZyZiv/1bc53f2c539033ebf9a121b1ef5970fe/snor-rider-biljett.png?w=600&fm=webp&q=70",
  paragraph: "Entré till parken och åkband. Obegränsat med åk hela dagen!",
  productsPricesHeading: "Förmiddagens biljettpriser",
  productsPrices: {
    type: "description",
    price: "125 kr",
  },
  buttonLabel: "Köp ticket to ride",
  buttonAction: action("Clicked"),
  ...pr,
});

type Tag = {
  id: string;
  title: string;
};
type TaggedData = {
  id: string;
  tags: Tag[];
};

const entranceTag: Tag = {
  id: "entr123",
  title: "Entré",
};
const rideTag: Tag = {
  id: "ride321",
  title: "Åkattraktioner",
};
const seasonPassTag: Tag = {
  id: "seas213",
  title: "Säsongskort",
};

const meta: Meta<ComponentProps<typeof StickyFilter> & Pick<ComponentProps<typeof NestedTagFilterer>, "filterTags">> = {
  title: "Blocks/ListBlock/StickyFilter",
  component: StickyFilter,
  args: {
    filterTags: [entranceTag, rideTag, seasonPassTag],
  },
};

export default meta;

const renderInListBlock = (
  filter: React.ComponentType<ListTransformerProps<ProductGroup<TaggedData>>>,
  sorter?: React.ComponentType<ListTransformerProps<ProductGroup<TaggedData>>>,
) => (
  <div>
    <nav className={styles.menu}>Home - Contact us</nav>
    <div className={styles.spacer} />
    <ListBlock
      data={[
        {
          headline: "Entrébiljetter",
          id: "grupp123",
          isExpanded: true,
          listObjects: [
            { ...exampleProduct({}), id: "bla1", tags: [entranceTag, rideTag] },
            {
              ...exampleProduct({ heading: "Entrébiljett", paragraph: "Endast entré inkluderat" }),
              id: "bla2",
              tags: [entranceTag],
            },
            {
              ...exampleProduct({ heading: "Åkband", paragraph: "Endast Ticket to ride, ingen entre" }),
              id: "bla3",
              tags: [rideTag],
            },
          ],
        },
        {
          headline: "Säsongskort",
          id: "grupp321",
          isExpanded: true,
          listObjects: [
            { ...exampleProduct({ heading: "Sommarkortet" }), id: "bla4", tags: [seasonPassTag, entranceTag] },
          ],
        },
      ]}
      renderer="ProductGroups"
      filter={filter}
      sorter={sorter}
    />
  </div>
);

export const Primary: StoryObj<typeof meta> = {
  args: {
    child: (ref, isSticky) => (
      <div className={`${styles.stickyParagraph} ${isSticky ? "stickied" : ""}`} ref={ref}>
        Gets stickied
        <span className={styles.hiddenUntilStickied}>This can only be seen after we are stuck</span>
      </div>
    ),
  },
  decorators: [
    (Story) => (
      <div>
        <h1>Some header</h1>
        <Story />
        <div style={{ height: "110vh" }}>Just some text</div>
      </div>
    ),
  ],
} satisfies StoryObj<typeof meta>;

