export const StickyFilterHeader = {
  render: (args) =>
    renderInListBlock((props) => (
      <StickyFilter
        {...args}
        child={(stickyRef, isSticky) => (
          <NestedTagFilterer
            filterMode="multiselect"
            filterTags={args.filterTags}
            header="Filtrera efter kategori"
            noFilterSelectedLabel="Visa alla"
            scrollRef={stickyRef}
            isStickied={isSticky}
            {...props}
          />
        )}
      />
    )),
  args: { child: () => <></> }, // Not used, since we pass it in `render
} satisfies StoryObj<typeof meta>;

export const OneStickyHeader = {
  render: (args) =>
    renderInListBlock(
      (props) => (
        <StickyFilter
          {...args}
          child={(stickyRef, isSticky) => (
            <NestedTagFilterer
              filterMode="multiselect"
              filterTags={args.filterTags}
              header="Filtrera efter kategori"
              noFilterSelectedLabel="Visa alla"
              scrollRef={stickyRef}
              isStickied={isSticky}
              {...props}
            />
          )}
        />
      ),
      (props) => (
        <Sorter
          noSortLabel="Ingen sortering"
          sortBys={["count"]}
          titles={(clause) => {
            switch (clause) {
              case "count":
                return "Antal val";
            }
            return undefined;
          }}
          comparator={(d, clause) => {
            if (clause === "count") return d.listObjects.length;
            return undefined;
          }}
          {...props}
        />
      ),
    ),
  args: { child: () => <></> }, // Not used, since we pass it in `render
} satisfies StoryObj<typeof meta>;
