// @ts-strict-ignore
import React, { useEffect, useMemo, useState } from "react";
import { LocationHelper } from "@/core/helpers";
import { ListTransformerProps, ListReceiverProps } from "../list-block";
import { ListTranformerHeader } from "../list-transformer-header/list-transformer-header";

type Tag = {
  id: string;
  title: string;
};
type NestedTaggedData = {
  listObjects: {
    tags: Tag[];
  }[];
};

function setHashInUrl(urlHashes: [string, string[]][]): void {
  LocationHelper.addHashToUrlWithoutReload(urlHashes.map(([key, value]) => ({ key, value })));
}

type TagFiltererProps = ListTransformerProps<NestedTaggedData> & {
  header?: string;
  noFilterSelectedLabel?: string;
  filterTags: Tag[];
  filterMode: "single" | "multiselect";
  /**
   * Useful when there are multiple filters on the same page.
   * Defaults to "filter".
   * Set urlHashParameter to empty string to not use url hash at all
   */
  urlHashParameter?: string;
  isStickied?: boolean;
  scrollRef?: React.RefObject<HTMLDivElement>;
};
export const NestedTagFilterer = (props: TagFiltererProps) => {
  const {
    data,
    children,
    header,
    noFilterSelectedLabel,
    filterTags,
    filterMode,
    urlHashParameter = "filter",
    isStickied = false,
    scrollRef,
  } = props;

  const filterTagsWithTrimmedTitle: TagFiltererProps["filterTags"] = useMemo(
    () =>
      filterTags.map((tag) => {
        return {
          ...tag,
          title: tag.title.trim(),
        };
      }),
    [filterTags],
  );

  const [selectedFilters, _setSelectedFilters] = useState<string[]>([]);
  const setSelectedFilters = (filters: string[]) => {
    _setSelectedFilters(filters);
    if (!urlHashParameter) return;

    const urlHashes = Object.entries(LocationHelper.getDecodedHashParams());
    if (filters.length === 0) {
      const updatedUrlHashes = urlHashes.filter(([key]) => key !== urlHashParameter);
      setHashInUrl(updatedUrlHashes);
      return;
    }
    const thisHash = urlHashes.find(([key]) => key === urlHashParameter);
    if (thisHash) {
      thisHash[1] = filters;
    } else {
      urlHashes.push([urlHashParameter, filters]);
    }
    setHashInUrl(urlHashes);
  };
  const toggleFilterSingleMode = (id: string) => setSelectedFilters(selectedFilters.includes(id) ? [] : [id]);
  const toggleFilterMultipleMode = (id: string) => {
    const afterRemoved = selectedFilters.filter((filter) => filter !== id);
    if (afterRemoved.length === selectedFilters.length) {
      // None was removed, so this tag should be toggled on
      setSelectedFilters([...afterRemoved, id]);
    } else {
      setSelectedFilters(afterRemoved);
    }
  };
  const toggleFilter = filterMode === "single" ? toggleFilterSingleMode : toggleFilterMultipleMode;

  useEffect(() => {
    if (!urlHashParameter) return;

    const { [urlHashParameter]: hashParam } = LocationHelper.getDecodedHashParams();
    if (!hashParam) return;

    const hashFilter = hashParam.flatMap((s) => s.split(","));

    _setSelectedFilters(
      filterTagsWithTrimmedTitle.filter(({ title }) => hashFilter.includes(title)).map((t) => t.title),
    );
  }, [urlHashParameter, filterTagsWithTrimmedTitle]);

  const scrollToTopOfSection = () => {
    if (!scrollRef?.current) return;

    // Cannot use `scrollRef.current` as it might be stickied, which makes the `scrollToPosition` math impossible.
    const siblings = [...scrollRef.current.parentElement.children];
    const nextElementIdx = siblings.findIndex((ch) => ch === scrollRef.current) + 1;
    const nextElement = siblings[nextElementIdx];
    const nextElementRect = nextElement.getBoundingClientRect();
    const offsetFromTop = window.scrollY;

    const headerHeight = scrollRef.current.getBoundingClientRect().height;

    const rem = 16;
    const menuAndStickyHeights = 3 * rem + headerHeight;

    const scrollToPosition = nextElementRect.top + offsetFromTop - menuAndStickyHeights - 0.5 * rem;

    // Not sure why timeout is necessary. Maybe it has to do with framer motion-animations. Maybe it's because we
    // rewrite the url hash (related to anchors). Maybe it's something else!
    setTimeout(() =>
      window.scrollTo({
        top: scrollToPosition,
        behavior: "smooth",
      }),
    );
  };

  const filteredData = data
    .map((group) => {
      const listObjects = group.listObjects.filter(({ tags }) => {
        return selectedFilters.length === 0 || (tags ?? []).some((tag) => selectedFilters.includes(tag.title));
      });
      return { ...group, listObjects };
    })
    .filter((gr) => gr.listObjects.length > 0);

  const tagPills = filterTagsWithTrimmedTitle.map(({ id, title }) => ({
    key: id,
    isSelected: selectedFilters.includes(title),
    onClick: () => {
      toggleFilter(title);
      scrollToTopOfSection();
    },
    children: title,
  }));
  const pills =
    noFilterSelectedLabel && filterTagsWithTrimmedTitle.length > 0
      ? [
          {
            key: "no-filter-selected",
            isSelected: selectedFilters.length === 0,
            onClick: () => {
              setSelectedFilters([]);
              scrollToTopOfSection();
            },
            children: noFilterSelectedLabel,
          },
          ...tagPills,
        ]
      : tagPills;

  return (
    <>
      <ListTranformerHeader pills={pills} header={header} isStickied={isStickied} scrollRef={scrollRef} />
      {React.Children.map(children, (child) => {
        if (!React.isValidElement<ListReceiverProps<NestedTaggedData>>(child)) {
          return child;
        }
        return React.cloneElement(child, { data: filteredData });
      })}
    </>
  );
};
