import React, { useEffect, useRef, useState } from "react";

export type StickyFilterProps = {
  child: (ref: React.RefObject<HTMLDivElement>, isStickied: boolean) => React.ReactElement;
};
export function StickyFilter({ child }: StickyFilterProps) {
  const [isStickied, setIsStickied] = useState(false);
  const [top, setTop] = useState(0);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (typeof window === "undefined" || !scrollRef?.current) return undefined;
    const element = scrollRef.current;

    const resizeObserver = new ResizeObserver(() => {
      const topValue = getComputedStyle(element).top;
      const topPx = topValue?.match(/(-?\d+)px/)?.[1];
      const topPixels = parseInt(topPx ?? "0", 10);

      setTop(topPixels);
    });
    resizeObserver.observe(element);
    return () => resizeObserver.unobserve(element);
  }, [scrollRef]);

  // Since we use the `position: sticky` we can use `IntersectionObserver` to observe whether its stickied or not
  useEffect(() => {
    if (typeof window === "undefined" || !scrollRef?.current) return undefined;
    const element = scrollRef.current;

    const observer = new IntersectionObserver(
      (entries) => {
        const isIntersecting = entries.some((e) => e.isIntersecting);
        setIsStickied(!isIntersecting);
      },
      {
        rootMargin: `${-(top + 1)}px 0px 0px 0px`,
        threshold: [1],
        // The root is explicitly set to `window.document` in order to work within storybook iframe. If it deosn't use
        // document, the entire viewport is considered instead, which is confusing in the storybook context.
        root: window.document,
      },
    );
    observer.observe(element);
    return () => observer.unobserve(element);
  }, [scrollRef, top]);

  return child(scrollRef, isStickied);
}
